import React, { useState, useEffect } from "react";
import "./AdminCommon.css";
import "./FeaturesSettings.css";

const FeaturesSettings = () => {
  const [t, setT] = useState({});
  const lang = localStorage.getItem("lang") || "en";
  const [features, setFeatures] = useState([]);

  useEffect(() => {
    fetch(`/${lang}.json`)
      .then((res) => res.json())
      .then((data) => setT(data))
      .catch((error) => console.error("Error loading translations:", error));
  }, [lang]);

  useEffect(() => {
    let active = true;
    const readSaved = () => {
      const saved = localStorage.getItem("features");
      if (!saved) return null;
      try {
        const parsed = JSON.parse(saved);
        return Array.isArray(parsed) ? parsed : null;
      } catch (error) {
        console.error("Invalid features data in localStorage:", error);
        return null;
      }
    };

    const savedFeatures = readSaved();
    if (savedFeatures) {
      setFeatures(savedFeatures);
      return;
    }

    fetch("/data.json")
      .then((res) => res.json())
      .then((data) => {
        if (active) setFeatures(data.features || []);
      })
      .catch((err) => console.error("Error loading default features:", err));

    return () => {
      active = false;
    };
  }, []);

  const handleChange = (index, field, value) => {
    const updatedFeatures = [...features];
    updatedFeatures[index][field] = value;
    setFeatures(updatedFeatures);
  };

  const handleSave = () => {
    // Save features to localStorage
    localStorage.setItem("features", JSON.stringify(features));
    alert(t.features_saved || "Features settings have been saved!");
  };

  return (
    <div className="admin-page">
      <h2>{t.features_settings || "Features Settings"}</h2>
      <table className="admin-features-table">
        <thead>
          <tr>
            <th>{t.feature_id || "Feature ID"}</th>
            <th>{t.display_name || "Display Name"}</th>
            <th>{t.description || "Description"}</th>
            <th>{t.path || "Path"}</th>
            <th>{t.visible || "Visible"}</th>
          </tr>
        </thead>
        <tbody>
          {features.map((feature, index) => (
            <tr key={feature.id}>
              <td>{feature.id}</td>
              <td>
                <input
                  type="text"
                  value={feature.displayName}
                  onChange={(e) =>
                    handleChange(index, "displayName", e.target.value)
                  }
                />
              </td>
              <td>
                <input
                  type="text"
                  value={feature.description}
                  onChange={(e) =>
                    handleChange(index, "description", e.target.value)
                  }
                />
              </td>
              <td>
                <input
                  type="text"
                  value={feature.path}
                  onChange={(e) => handleChange(index, "path", e.target.value)}
                />
              </td>
              <td>
                <input
                  type="checkbox"
                  checked={feature.isVisible !== false}
                  onChange={(e) =>
                    handleChange(index, "isVisible", e.target.checked)
                  }
                />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <div className="admin-button-group">
        <button className="admin-btn admin-btn-primary" onClick={handleSave}>
          <i className="fas fa-save"></i> {t.save_changes || "Save Changes"}
        </button>
      </div>
    </div>
  );
};

export default FeaturesSettings;


